    tx.commit().await?;
    let result = rows.into_iter().map(|(h, hm, cnt)| serde_json::json!({"hour": h, "harmonic_mean_categories": hm, "event_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
