/// GET /api/v1/calendars/:cal_id/events-by-range/attendees-count-above-p05-by-weekday — contagem de eventos com participantes acima do P05 × dia da semana. Sprint #4901.
async fn events_by_range_attendees_count_above_p05_by_weekday(
    State(state): State<AppState>,
    ctx: RequestCtx,
    Path(cal_id): Path<uuid::Uuid>,
    Query(q): Query<EventsByRangeRruleStatsQuery>,
) -> Result<Json<serde_json::Value>, CalendarError> {
    if let (Some(a), Some(b)) = (q.after, q.before) {
        if a >= b { return Err(CalendarError::BadRequest("after must be before before".into())); }
    }
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(i32, Option<f64>, i64, i64)> = sqlx::query_as(
        "SELECT EXTRACT(DOW FROM dtstart AT TIME ZONE 'UTC')::INT AS weekday, \
                PERCENTILE_CONT(0.05) WITHIN GROUP (ORDER BY COALESCE(array_length(attendees, 1), 0))::FLOAT8 AS p05_attendees, \
                COUNT(*) FILTER (WHERE COALESCE(array_length(attendees, 1), 0) > \
                    PERCENTILE_CONT(0.05) WITHIN GROUP (ORDER BY COALESCE(array_length(attendees, 1), 0)) OVER ())::BIGINT AS count_above_p05, \
                COUNT(*)::BIGINT AS cnt \
         FROM calendar_events \
         WHERE tenant_id = $1 AND calendar_id = $2 \
           AND ($3::TIMESTAMPTZ IS NULL OR dtstart >= $3) \
           AND ($4::TIMESTAMPTZ IS NULL OR dtstart <= $4) \
         GROUP BY EXTRACT(DOW FROM dtstart AT TIME ZONE 'UTC') ORDER BY weekday",
    ).bind(ctx.tenant_id).bind(cal_id).bind(q.after).bind(q.before).fetch_all(&mut *tx).await?;
    tx.commit().await?;
    let result = rows.into_iter().map(|(wd, p05, above, cnt)| serde_json::json!({"weekday": wd, "p05_attendees": p05, "count_above_p05": above, "event_count": cnt})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

