/// GET /api/v1/calendars/:cal_id/events-by-range/categories-p10-by-month — P10 categories count × month. Sprint #1764.
async fn events_by_range_categories_p10_by_month(
    State(state): State<AppState>,
    ctx:          RequestCtx,
    Path(cal_id): Path<Uuid>,
    Query(q):     Query<EventsByRangeRruleStatsQuery>,
) -> Result<Json<serde_json::Value>, CalendarError> {
    if let (Some(a), Some(b)) = (q.after, q.before) {
        if a >= b { return Err(CalendarError::BadRequest("after must be before before".into())); }
    }
    let mut tx = begin_tenant_tx(state.db(), ctx.tenant_id).await?;
    let rows: Vec<(i32, f64, i64)> = sqlx::query_as(
        "SELECT EXTRACT(MONTH FROM dtstart AT TIME ZONE 'UTC')::INT AS month, \
         PERCENTILE_CONT(0.10) WITHIN GROUP (ORDER BY COALESCE(array_length(categories, 1), 0))::FLOAT8 AS p10_categories, \
         COUNT(*)::BIGINT AS event_count \
         FROM calendar_events \
         WHERE tenant_id = $1 AND calendar_id = $2 \
         AND ($3::timestamptz IS NULL OR dtstart >= $3) \
         AND ($4::timestamptz IS NULL OR dtstart < $4) \
         GROUP BY month ORDER BY month ASC",
    )
    .bind(ctx.tenant_id)
    .bind(cal_id)
    .bind(q.after)
    .bind(q.before)
    .fetch_all(&mut *tx)
    .await?;
    tx.commit().await?;
    const MONTH_NAMES: [&str; 12] = ["January","February","March","April","May","June","July","August","September","October","November","December"];
    let result: Vec<serde_json::Value> = rows
        .into_iter()
        .map(|(month, p10, cnt)| {
            let name = MONTH_NAMES.get((month - 1) as usize).copied().unwrap_or("Unknown");
            serde_json::json!({"month": month, "month_name": name, "p10_categories_count": p10, "event_count": cnt})
        })
        .collect();
    Ok(Json(serde_json::json!({"rows": result})))
}

