/// GET /api/v1/calendars/:cal_id/events-by-range/has-attendees-by-weekday — with/without attendees × DOW. Sprint #1429.
async fn events_by_range_has_attendees_by_weekday(
    State(state): State<AppState>,
    ctx:          RequestCtx,
    Path(cal_id): Path<Uuid>,
    Query(q):     Query<EventsByRangeRruleStatsQuery>,
) -> Result<Json<serde_json::Value>> {
    if let (Some(a), Some(b)) = (q.after, q.before) {
        if a >= b { return Err(CalendarError::BadRequest("after must be < before".into())); }
    }
    let pool = state.db_or_unavailable()?;
    let mut tx = begin_tenant_tx(pool, ctx.tenant_id).await?;

    let rows: Vec<(i32, i64, i64)> = sqlx::query_as(
        "SELECT \
            EXTRACT(DOW FROM dtstart AT TIME ZONE 'UTC')::INT AS dow, \
            COUNT(*) FILTER (WHERE attendees IS NOT NULL AND jsonb_array_length(attendees) > 0)::BIGINT AS with_attendees, \
            COUNT(*) FILTER (WHERE attendees IS NULL OR jsonb_array_length(attendees) = 0)::BIGINT  AS without_attendees \
           FROM calendar_events \
          WHERE tenant_id = $1 AND calendar_id = $2 \
            AND dtstart IS NOT NULL \
            AND ($3::timestamptz IS NULL OR dtstart >= $3) \
            AND ($4::timestamptz IS NULL OR dtstart <  $4) \
          GROUP BY dow \
          ORDER BY dow ASC",
    )
    .bind(ctx.tenant_id).bind(cal_id).bind(q.after).bind(q.before)
    .fetch_all(&mut *tx).await?;
    tx.commit().await?;

    const DAY_NAMES: [&str; 7] = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
    let result: Vec<serde_json::Value> = rows.into_iter()
        .map(|(d, with_att, without_att)| {
            let day_name = DAY_NAMES.get(d as usize).copied().unwrap_or("Unknown");
            serde_json::json!({"dow": d, "day_name": day_name, "with_attendees": with_att, "without_attendees": without_att})
        })
        .collect();
    Ok(Json(serde_json::json!({"calendar_id": cal_id, "rows": result})))
}

