    let updated = EventRepo::new(pool)
        .set_class_range(ctx.tenant_id, cal_id, &q.class, q.after, q.before)
        .await?;

    Ok(Json(serde_json::json!({
        "calendar_id": cal_id,
        "class":       q.class,
        "updated":     updated,
    })))
