/// GET /api/v1/calendars/:cal_id/events-by-range/class-count-above-mean-by-weekday — Sprint #6061.
async fn events_by_range_class_count_above_mean_by_weekday(
    State(state): State<AppState>, ctx: RequestCtx,
    Path(cal_id): Path<uuid::Uuid>,
    Query(q): Query<EventsByRangeRruleStatsQuery>
) -> Result<Json<serde_json::Value>, CalendarError> {
    let mut tx = state.db.begin().await?;
    let rows: Vec<(i32, Option<f64>, i64, i64)> = sqlx::query_as(
        "SELECT EXTRACT(DOW FROM start_at)::INT AS dow, \
         AVG(COALESCE(regexp_count(ical_raw, '^CLASS'), 0)) OVER ()::FLOAT8 AS mean_class_count, \
         COUNT(*) FILTER (WHERE COALESCE(regexp_count(ical_raw, '^CLASS'), 0) > AVG(COALESCE(regexp_count(ical_raw, '^CLASS'), 0)) OVER ())::BIGINT AS count_above_mean, \
         COUNT(*)::BIGINT AS event_count \
         FROM calendar_events WHERE calendar_id = $1 AND tenant_id = $2 AND ($3::TIMESTAMPTZ IS NULL OR start_at >= $3) AND ($4::TIMESTAMPTZ IS NULL OR start_at < $4) \
         GROUP BY dow ORDER BY dow",
    ).bind(cal_id).bind(ctx.tenant_id).bind(q.after).bind(q.before).fetch_all(&mut *tx).await?;
    tx.commit().await?;
    let result = rows.into_iter().map(|(d, p, a, c)| serde_json::json!({"dow": d, "mean_class_count": p, "count_above_mean": a, "event_count": c})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

