async fn events_by_range_dtstamp_count_below_mean_by_month(
    State(state): State<AppState>, ctx: RequestCtx,
    Path(cal_id): Path<uuid::Uuid>,
    Query(q): Query<EventsByRangeRruleStatsQuery>
) -> Result<Json<serde_json::Value>, CalendarError> {
    let mut tx = state.db.begin().await?;
    let rows: Vec<(i32, Option<f64>, i64, i64)> = sqlx::query_as(
        "SELECT EXTRACT(MONTH FROM start_at)::INT AS month, \
         AVG(COALESCE(regexp_count(ical_raw, '^DTSTAMP'), 0)) OVER ()::FLOAT8 AS mean_dtstamp_count, \
         COUNT(*) FILTER (WHERE COALESCE(regexp_count(ical_raw, '^DTSTAMP'), 0) < AVG(COALESCE(regexp_count(ical_raw, '^DTSTAMP'), 0)) OVER ())::BIGINT AS count_below_mean, \
         COUNT(*)::BIGINT AS event_count \
         FROM calendar_events WHERE calendar_id = $1 AND tenant_id = $2 AND ($3::TIMESTAMPTZ IS NULL OR start_at >= $3) AND ($4::TIMESTAMPTZ IS NULL OR start_at < $4) \
         GROUP BY month ORDER BY month",
    ).bind(cal_id).bind(ctx.tenant_id).bind(q.after).bind(q.before).fetch_all(&mut *tx).await?;
    tx.commit().await?;
    let result = rows.into_iter().map(|(d, p, a, c)| serde_json::json!({"month": d, "mean_dtstamp_count": p, "count_below_mean": a, "event_count": c})).collect::<Vec<_>>();
    Ok(Json(serde_json::json!({"rows": result})))
}

