    tx.commit().await?;
    let result = rows.into_iter().map(|(d, m, a, c)| serde_json::json!({"dow": d, "mean_ical_scheduleexpired_count": m, "count_above_mean": a, "event_count": c})).collect::<Vec<_>>();
